mod parser;
mod filter;
mod substitution;
mod colors;

use anyhow::Result;
use clap::Parser;
use std::fs;
use std::io::{self, BufRead, BufReader, Read};
use std::path::PathBuf;

#[derive(Parser, Debug)]
#[command(name = "fblog")]
#[command(about = "A small tool to view json log files.", long_about = None)]
#[command(version = "4.17.0")]
struct Args {
    /// Sets the input file to use, otherwise assumes stdin
    #[arg(value_name = "INPUT", default_value = "-")]
    input: String,

    /// Adds additional values
    #[arg(short, long, value_name = "additional-value")]
    additional_value: Vec<String>,

    /// Configuration file to load
    #[arg(long, value_name = "config-file")]
    config_file: Option<PathBuf>,

    /// Adds an additional key to detect the message in the log entry
    #[arg(short, long, value_name = "message-key")]
    message_key: Vec<String>,

    /// Prints lua init expressions
    #[arg(long)]
    print_lua: bool,

    /// Adds an additional key to detect the time in the log entry
    #[arg(short, long, value_name = "time-key")]
    time_key: Vec<String>,

    /// Adds an additional key to detect the level in the log entry
    #[arg(short, long, value_name = "level-key")]
    level_key: Vec<String>,

    /// Rewrite the log level from one value to another
    #[arg(long, value_name = "from=to")]
    map_level: Vec<String>,

    /// Dumps all values
    #[arg(short, long)]
    dump_all: bool,

    /// Excludes values (--dump-all is enabled implicitly)
    #[arg(short, long, value_name = "excluded-value")]
    excluded_value: Vec<String>,

    /// Consider all text before opening curly brace as prefix
    #[arg(short, long)]
    with_prefix: bool,

    /// Lua expression to filter log entries
    #[arg(short, long, value_name = "filter")]
    filter: Option<String>,

    /// Disable implicit return statement in filter
    #[arg(long)]
    no_implicit_filter_return_statement: bool,

    /// Formats the main fblog output
    #[arg(long, value_name = "main-line-format")]
    main_line_format: Option<String>,

    /// Formats the additional value fblog output
    #[arg(long, value_name = "additional-value-format")]
    additional_value_format: Option<String>,

    /// Enable substitution of placeholders in the log messages
    #[arg(short, long)]
    substitute: bool,

    /// Use this key as the source of substitutions for the message
    #[arg(short, long, value_name = "context-key")]
    context_key: Option<String>,

    /// The format that should be used for substituting values in the message
    #[arg(short = 'F', long, value_name = "placeholder-format")]
    placeholder_format: Option<String>,
}

fn main() -> Result<()> {
    let args = Args::parse();

    if args.print_lua {
        println!("-- fblog lua expressions");
        return Ok(());
    }

    let mut config = config::load_config(&args)?;

    // Override config with command line args
    if !args.message_key.is_empty() {
        for key in args.message_key {
            config.message_keys.insert(0, key);
        }
    }

    if !args.time_key.is_empty() {
        for key in args.time_key {
            config.time_keys.insert(0, key);
        }
    }

    if !args.level_key.is_empty() {
        for key in args.level_key {
            config.level_keys.insert(0, key);
        }
    }

    if let Some(fmt) = &args.main_line_format {
        config.main_line_format = fmt.clone();
    }

    if let Some(fmt) = &args.additional_value_format {
        config.additional_value_format = fmt.clone();
    }

    // Build level mappings
    let mut level_map = config.level_map.clone();
    for mapping in &args.map_level {
        if let Some((from, to)) = mapping.split_once('=') {
            level_map.insert(from.trim().to_string(), to.trim().to_string());
        }
    }

    // Process input
    let reader: Box<dyn Read> = if args.input == "-" {
        Box::new(io::stdin())
    } else {
        Box::new(fs::File::open(&args.input)?)
    };

    let buf_reader = BufReader::new(reader);
    let mut line_no = 0;

    for line in buf_reader.lines() {
        line_no += 1;
        let line = line?;

        // Try to parse as JSON
        if let Ok(json_value) = serde_json::from_str::<serde_json::Value>(&line) {
            let mut entry = log_entry::LogEntry::from_json(json_value, &config);

            // Apply level mapping
            if let Some(mapped_level) = level_map.get(&entry.level) {
                entry.level = mapped_level.clone();
            }

            // Apply filter if provided
            if let Some(ref filter_expr) = args.filter {
                if !filter::evaluate_filter(&entry, filter_expr, args.no_implicit_filter_return_statement)? {
                    continue;
                }
            }

            // Apply substitution if enabled
            if args.substitute {
                if let Some(ref ctx_key) = args.context_key {
                    entry.substitute(&args.placeholder_format.as_deref().unwrap_or("#{key}"));
                }
            }

            // Format and print
            if args.with_prefix && entry.prefix.is_some() {
                formatter::format_with_prefix(&entry, &config, &args.additional_value, args.dump_all, &args.excluded_value);
            } else if args.dump_all || !args.excluded_value.is_empty() {
                formatter::format_full(&entry, &config, &args.additional_value, &args.excluded_value);
            } else {
                formatter::format_main(&entry, &config, &args.additional_value);
            }
        } else {
            // Non-JSON line - print as is with warning marker
            if line.contains('{') {
                println!("[1;38;2;255;135;22m??? >[0m {}", line);
            } else {
                println!("[1;38;2;255;135;22m??? >[0m {}", line);
            }
        }
    }

    Ok(())
}
EOFMAIN

