use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub message_keys: Vec<String>,
    pub time_keys: Vec<String>,
    pub level_keys: Vec<String>,
    pub dump_all_exclude: Vec<String>,
    pub always_print_fields: Vec<String>,
    pub main_line_format: String,
    pub additional_value_format: String,
    #[serde(default)]
    pub level_map: HashMap<String, String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            message_keys: vec![
                "short_message".to_string(),
                "msg".to_string(),
                "message".to_string(),
            ],
            time_keys: vec![
                "timestamp".to_string(),
                "time".to_string(),
                "@timestamp".to_string(),
            ],
