use crate::config::Config;
use serde_json::{json, Value};
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct LogEntry {
    pub message: String,
    pub timestamp: String,
    pub level: String,
    pub prefix: Option<String>,
    pub fields: BTreeMap<String, Value>,
    pub raw_json: Value,
}

impl LogEntry {
    pub fn from_json(mut value: Value, config: &Config) -> Self {
        let mut entry = LogEntry {
            message: String::new(),
            timestamp: String::new(),
            level: "UNKNOWN".to_string(),
            prefix: None,
            fields: BTreeMap::new(),
            raw_json: value.clone(),
        };

        if let Some(obj) = value.as_object_mut() {
            // Extract message
            for key in &config.message_keys {
                if let Some(msg) = obj.get(key) {
                    if let Some(s) = msg.as_str() {
                        entry.message = s.to_string();
                    } else {
                        entry.message = msg.to_string();
                    }
                    break;
                }
            }

            // Extract timestamp
            for key in &config.time_keys {
                if let Some(ts) = obj.get(key) {
                    if let Some(s) = ts.as_str() {
                        entry.timestamp = s.to_string();
                    } else {
                        entry.timestamp = ts.to_string();
                    }
                    break;
                }
            }

            // Extract level
            for key in &config.level_keys {
                if let Some(lvl) = obj.get(key) {
                    if let Some(s) = lvl.as_str() {
                        entry.level = s.to_string();
                    } else {
                        entry.level = lvl.to_string();
                    }
                    break;
                }
            }

            // Collect all fields
            for (k, v) in obj {
                entry.fields.insert(k.clone(), v.clone());
            }
        }

        entry
    }

    pub fn substitute(&mut self, placeholder_format: &str) {
        // Get context data from fields
        if let Some(context) = self.fields.get("context") {
            match context {
                Value::Object(ctx) => {
                    for (key, val) in ctx {
                        let placeholder = placeholder_format.replace("key", key);
                        let val_str = match val {
                            Value::String(s) => s.clone(),
                            Value::Object(o) if o.len() == 1 => {
                                o.values().next().map(|v| v.to_string()).unwrap_or_default()
                            }
                            _ => val.to_string(),
                        };
                        self.message = self.message.replace(&placeholder, &val_str);
                    }
                }
                Value::Array(arr) => {
                    for (idx, val) in arr.iter().enumerate() {
                        let placeholder = placeholder_format.replace("key", &idx.to_string());
                        let val_str = match val {
                            Value::Array(a) if a.len() == 1 => {
                                a[0].as_str().unwrap_or("").to_string()
                            }
                            _ => val.to_string(),
                        };
                        self.message = self.message.replace(&placeholder, &val_str);
                    }
                }
                _ => {}
            }
        }
    }
}
