use std::fs;
use std::io::{self, BufRead, BufReader, Read};

#[derive(Debug)]
struct Args {
    input: String,
    additional_value: Vec<String>,
    config_file: Option<String>,
    message_key: Vec<String>,
    time_key: Vec<String>,
    level_key: Vec<String>,
    dump_all: bool,
    excluded_value: Vec<String>,
    with_prefix: bool,
    filter: Option<String>,
    map_level: Vec<String>,
}

fn parse_args() -> Args {
    let mut args = std::env::args().skip(1);
    let mut result = Args {
        input: "-".to_string(),
        additional_value: Vec::new(),
        config_file: None,
        message_key: Vec::new(),
        time_key: Vec::new(),
        level_key: Vec::new(),
        dump_all: false,
        excluded_value: Vec::new(),
        with_prefix: false,
        filter: None,
        map_level: Vec::new(),
    };

    let mut expecting_value = false;
    let mut expecting_key = "";

    while let Some(arg) = args.next() {
        if expecting_value {
            match expecting_key {
                "-a" | "--additional-value" => result.additional_value.push(arg),
                "-m" | "--message-key" => result.message_key.push(arg),
                "-t" | "--time-key" => result.time_key.push(arg),
                "-l" | "--level-key" => result.level_key.push(arg),
                "-x" | "--excluded-value" => result.excluded_value.push(arg),
                "-f" | "--filter" => result.filter = Some(arg),
                "--map-level" => result.map_level.push(arg),
                "--config-file" => result.config_file = Some(arg),
                _ => {}
            }
            expecting_value = false;
            continue;
        }

        match arg.as_str() {
            "-a" | "--additional-value" | "-m" | "--message-key" | "-t" | "--time-key" |
            "-l" | "--level-key" | "-x" | "--excluded-value" | "-f" | "--filter" |
            "--map-level" | "--config-file" => {
                expecting_key = arg.as_str();
                expecting_value = true;
            }
            "-d" | "--dump-all" => result.dump_all = true,
            "-p" | "--with-prefix" => result.with_prefix = true,
            "--help" => {
                print_help();
                std::process::exit(0);
            }
            "--version" => {
                println!("fblog 4.17.0");
                std::process::exit(0);
            }
            _ if !arg.starts_with('-') => {
                result.input = arg;
            }
            _ => {}
        }
    }

    result
}

fn print_help() {
    println!("json log viewer

Usage: executable [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Sets the input file to use, otherwise assumes stdin [default: -]

Options:
  -a, --additional-value <additional-value>
          adds additional values
      --config-file <config-file>
          configuration file to load
  -m, --message-key <message-key>
          Adds an additional key to detect the message in the log entry. The first matching key will be assigned to `fblog_message`.
  -t, --time-key <time-key>
          Adds an additional key to detect the time in the log entry. The first matching key will be assigned to `fblog_timestamp`.
  -l, --level-key <level-key>
          Adds an additional key to detect the level in the log entry. The first matching key will be assigned to `fblog_level`.
      --map-level <from=to>
          Rewrite the log level from one value to another.
  -d, --dump-all
          dumps all values
  -x, --excluded-value <excluded-value>
          Excludes values (--dump-all is enabled implicitly)
  -p, --with-prefix
          consider all text before opening curly brace as prefix
  -f, --filter <filter>
          lua expression to filter log entries
  -h, --help
          Print help
  -V, --version
          Print version");
}

fn main() -> std::io::Result<()> {
    let args = parse_args();
    let mut config = config::load_config();

    // Override config with command line args
    if !args.message_key.is_empty() {
        for key in args.message_key {
            config.message_keys.insert(0, key);
        }
    }

    if !args.time_key.is_empty() {
        for key in args.time_key {
            config.time_keys.insert(0, key);
        }
    }

    if !args.level_key.is_empty() {
        for key in args.level_key {
            config.level_keys.insert(0, key);
        }
    }

    // Build level mappings
    let mut level_map = config.level_map.clone();
    for mapping in &args.map_level {
        if let Some((from, to)) = mapping.split_once('=') {
            level_map.insert(from.trim().to_string(), to.trim().to_string());
        }
    }

    // Process input
    let reader: Box<dyn Read> = if args.input == "-" {
        Box::new(io::stdin())
    } else {
        Box::new(fs::File::open(&args.input)?)
    };

    let buf_reader = BufReader::new(reader);

    for line in buf_reader.lines() {
        let line = line?;

        // Try to parse as JSON
        if let Ok(json_value) = serde_json::from_str::<serde_json::Value>(&line) {
            let mut entry = log_entry::LogEntry::from_json(json_value, &config);

            // Apply level mapping
            if let Some(mapped_level) = level_map.get(&entry.level) {
                entry.level = mapped_level.clone();
            }

            // Format and print
            if args.with_prefix && entry.prefix.is_some() {
                formatter::format_with_prefix(&entry, &config, &args.additional_value, args.dump_all, &args.excluded_value);
            } else if args.dump_all || !args.excluded_value.is_empty() {
                formatter::format_full(&entry, &config, &args.additional_value, &args.excluded_value);
            } else {
                formatter::format_main(&entry, &config, &args.additional_value);
            }
        } else {
            // Non-JSON line - print as is with warning marker
            println!("[1;38;2;255;135;22m??? >[0m {}", line);
        }
    }

    Ok(())
}
