pub struct LogEntry {
    pub message: String,
    pub timestamp: String,
    pub level: String,
    pub prefix: Option<String>,
    pub fields: BTreeMap<String, Value>,
}

impl LogEntry {
    pub fn from_json(mut value: Value, config: &Config) -> Self {
        let mut entry = LogEntry {
            message: String::new(),
            timestamp: String::new(),
            level: "UNKNOWN".to_string(),
            prefix: None,
            fields: BTreeMap::new(),
        };

        if let Some(obj) = value.as_object_mut() {
            // Extract message
            for key in &config.message_keys {
                if let Some(msg) = obj.get(key) {
                    if let Some(s) = msg.as_str() {
                        entry.message = s.to_string();
                    } else {
                        entry.message = msg.to_string();
                    }
                    break;
                }
            }

            // Extract timestamp
            for key in &config.time_keys {
                if let Some(ts) = obj.get(key) {
                    if let Some(s) = ts.as_str() {
                        entry.timestamp = s.to_string();
                    } else {
                        entry.timestamp = ts.to_string();
                    }
                    break;
                }
            }

            // Extract level
            for key in &config.level_keys {
                if let Some(lvl) = obj.get(key) {
                    if let Some(s) = lvl.as_str() {
                        entry.level = s.to_string();
                    } else {
                        entry.level = lvl.to_string();
                    }
                    break;
                }
            }

            // Collect all fields
            for (k, v) in obj {
                entry.fields.insert(k.clone(), v.clone());
            }
        }

        entry
    }
}
