use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
pub enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

impl JsonValue {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            JsonValue::String(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_object(&self) -> Option<&BTreeMap<String, JsonValue>> {
        match self {
            JsonValue::Object(obj) => Some(obj),
            _ => None,
        }
    }

    pub fn as_array(&self) -> Option<&Vec<JsonValue>> {
        match self {
            JsonValue::Array(arr) => Some(arr),
            _ => None,
        }
    }

    pub fn get(&self, key: &str) -> Option<&JsonValue> {
        match self {
            JsonValue::Object(obj) => obj.get(key),
            _ => None,
        }
    }

    pub fn to_string(&self) -> String {
        match self {
            JsonValue::Null => "null".to_string(),
            JsonValue::Bool(b) => b.to_string(),
            JsonValue::Number(n) => {
                if n.fract() == 0.0 && n.is_finite() {
                    format!("{}", n as i64)
                } else {
                    n.to_string()
                }
            }
            JsonValue::String(s) => s.clone(),
            JsonValue::Array(arr) => {
                let items: Vec<String> = arr.iter().map(|v| v.to_string()).collect();
                format!("[{}]", items.join(", "))
            }
            JsonValue::Object(_) => "{...}".to_string(),
        }
    }
}

pub fn parse_json_object(input: &str) -> Option<BTreeMap<String, JsonValue>> {
    let input = input.trim();
    if !input.starts_with('{') || !input.ends_with('}') {
        return None;
    }

    let mut parser = JsonParser::new(input);
    match parser.parse_value() {
        Some(JsonValue::Object(obj)) => Some(obj),
        _ => None,
    }
}

struct JsonParser {
    chars: Vec<char>,
    pos: usize,
}

impl JsonParser {
    fn new(input: &str) -> Self {
        JsonParser {
            chars: input.chars().collect(),
            pos: 0,
        }
    }

    fn current(&self) -> Option<char> {
        if self.pos < self.chars.len() {
            Some(self.chars[self.pos])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        self.pos += 1;
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.current() {
            if c.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Option<JsonValue> {
        self.skip_whitespace();
        match self.current()? {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(JsonValue::String),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            '-' | '0'..='9' => self.parse_number(),
            _ => None,
        }
    }

    fn parse_object(&mut self) -> Option<JsonValue> {
        self.advance(); // consume '{'
        let mut obj = BTreeMap::new();

        self.skip_whitespace();
        if self.current() == Some('}') {
            self.advance();
            return Some(JsonValue::Object(obj));
        }

        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;

            self.skip_whitespace();
            if self.current() != Some(':') {
                return None;
            }
            self.advance();

            let value = self.parse_value()?;
            obj.insert(key, value);

            self.skip_whitespace();
            match self.current() {
                Some(',') => {
                    self.advance();
                }
                Some('}') => {
                    self.advance();
                    break;
                }
                _ => return None,
            }
        }

        Some(JsonValue::Object(obj))
    }

    fn parse_array(&mut self) -> Option<JsonValue> {
        self.advance(); // consume '['
        let mut arr = Vec::new();

        self.skip_whitespace();
        if self.current() == Some(']') {
            self.advance();
            return Some(JsonValue::Array(arr));
        }

        loop {
            arr.push(self.parse_value()?);

            self.skip_whitespace();
            match self.current() {
                Some(',') => {
                    self.advance();
                }
                Some(']') => {
                    self.advance();
                    break;
                }
                _ => return None,
            }
        }

        Some(JsonValue::Array(arr))
    }

    fn parse_string(&mut self) -> Option<String> {
        if self.current() != Some('"') {
            return None;
        }
        self.advance(); // consume opening '"'

        let mut result = String::new();
        loop {
            match self.current()? {
                '"' => {
                    self.advance();
                    return Some(result);
                }
                '\\' => {
                    self.advance();
                    match self.current()? {
                        '"' | '\\' | '/' => {
                            result.push(self.current()?);
                            self.advance();
                        }
                        'b' => {
                            result.push('\x08');
                            self.advance();
                        }
                        'f' => {
                            result.push('\x0c');
                            self.advance();
                        }
                        'n' => {
                            result.push('\n');
                            self.advance();
                        }
                        'r' => {
                            result.push('\r');
                            self.advance();
                        }
                        't' => {
                            result.push('\t');
                            self.advance();
                        }
                        'u' => {
                            self.advance();
                            let mut code = String::new();
                            for _ in 0..4 {
                                code.push(self.current()?);
                                self.advance();
                            }
                            if let Ok(code_point) = u32::from_str_radix(&code, 16) {
                                if let Some(ch) = char::from_u32(code_point) {
                                    result.push(ch);
                                }
                            }
                        }
                        _ => return None,
                    }
                }
                c => {
                    result.push(c);
                    self.advance();
                }
            }
        }
    }

    fn parse_number(&mut self) -> Option<JsonValue> {
        let start = self.pos;

        if self.current() == Some('-') {
            self.advance();
        }

        if self.current() == Some('0') {
            self.advance();
        } else {
            while let Some(c) = self.current() {
                if c.is_ascii_digit() {
                    self.advance();
                } else {
                    break;
                }
            }
        }

        if self.current() == Some('.') {
            self.advance();
            while let Some(c) = self.current() {
                if c.is_ascii_digit() {
                    self.advance();
                } else {
                    break;
                }
            }
        }

        if self.current() == Some('e') || self.current() == Some('E') {
            self.advance();
            if self.current() == Some('+') || self.current() == Some('-') {
                self.advance();
            }
            while let Some(c) = self.current() {
                if c.is_ascii_digit() {
                    self.advance();
                } else {
                    break;
                }
            }
        }

        let num_str: String = self.chars[start..self.pos].iter().collect();
        num_str.parse::<f64>().ok().map(JsonValue::Number)
    }

    fn parse_bool(&mut self) -> Option<JsonValue> {
        if self.pos + 4 <= self.chars.len() {
            let word: String = self.chars[self.pos..self.pos + 4].iter().collect();
            if word == "true" {
                self.pos += 4;
                return Some(JsonValue::Bool(true));
            }
        }
        if self.pos + 5 <= self.chars.len() {
            let word: String = self.chars[self.pos..self.pos + 5].iter().collect();
            if word == "false" {
                self.pos += 5;
                return Some(JsonValue::Bool(false));
            }
        }
        None
    }

    fn parse_null(&mut self) -> Option<JsonValue> {
        if self.pos + 4 <= self.chars.len() {
            let word: String = self.chars[self.pos..self.pos + 4].iter().collect();
            if word == "null" {
                self.pos += 4;
                return Some(JsonValue::Null);
            }
        }
        None
    }
}
