mod json;

use std::fs;
use std::io::{self, BufRead, BufReader, Read};

#[derive(Debug)]
struct Args {
    input: String,
    additional_value: Vec<String>,
    dump_all: bool,
    excluded_value: Vec<String>,
    with_prefix: bool,
    map_level: Vec<String>,
}

fn parse_args() -> Args {
    let args_vec: Vec<String> = std::env::args().skip(1).collect();
    let mut result = Args {
        input: "-".to_string(),
        additional_value: Vec::new(),
        dump_all: false,
        excluded_value: Vec::new(),
        with_prefix: false,
        map_level: Vec::new(),
    };

    let mut i = 0;
    while i < args_vec.len() {
        let arg = &args_vec[i];

        match arg.as_str() {
            "-a" | "--additional-value" => {
                if i + 1 < args_vec.len() {
                    result.additional_value.push(args_vec[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-x" | "--excluded-value" => {
                if i + 1 < args_vec.len() {
                    result.excluded_value.push(args_vec[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--map-level" => {
                if i + 1 < args_vec.len() {
                    result.map_level.push(args_vec[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-d" | "--dump-all" => {
                result.dump_all = true;
                i += 1;
            }
            "-p" | "--with-prefix" => {
                result.with_prefix = true;
                i += 1;
            }
            "--help" => {
                print_help();
                std::process::exit(0);
            }
            "--version" => {
                println!("fblog 4.17.0");
                std::process::exit(0);
            }
            _ if !arg.starts_with('-') => {
                result.input = arg.clone();
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }

    result
}

fn print_help() {
    println!("json log viewer

Usage: executable [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Sets the input file to use, otherwise assumes stdin [default: -]

Options:
  -a, --additional-value <additional-value>
          adds additional values
  -d, --dump-all
          dumps all values
  -x, --excluded-value <excluded-value>
          Excludes values (--dump-all is enabled implicitly)
  -p, --with-prefix
          consider all text before opening curly brace as prefix
  --map-level <from=to>
          Rewrite the log level from one value to another.
  -h, --help
          Print help
  -V, --version
          Print version");
}

fn main() -> std::io::Result<()> {
    let args = parse_args();
    let config = config::load_config();

