use crate::json::JsonValue;
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct LogEntry {
    pub message: String,
    pub timestamp: String,
    pub level: String,
    pub prefix: Option<String>,
    pub fields: BTreeMap<String, JsonValue>,
}

impl LogEntry {
    pub fn from_json(obj: BTreeMap<String, JsonValue>, config: &Config) -> Self {
        let mut entry = LogEntry {
            message: String::new(),
            timestamp: String::new(),
            level: "UNKNOWN".to_string(),
            prefix: None,
            fields: obj.clone(),
        };

        // Extract message
        for key in &config.message_keys {
            if let Some(msg) = obj.get(key) {
                if let Some(s) = msg.as_str() {
                    entry.message = s.to_string();
                } else {
                    entry.message = msg.to_string();
                }
                break;
            }
        }

        // Extract timestamp
        for key in &config.time_keys {
            if let Some(ts) = obj.get(key) {
                if let Some(s) = ts.as_str() {
                    entry.timestamp = s.to_string();
                } else {
                    entry.timestamp = ts.to_string();
                }
                break;
            }
