use crate::config::Config;
use crate::log_entry::LogEntry;
use crate::json::JsonValue;

pub fn format_main(entry: &LogEntry, _config: &Config, additional: &[String]) {
    let timestamp = truncate_timestamp(&entry.timestamp);
    let level_colored = format_level_colored(&entry.level);

    print!("\x1b[1m{:19}\x1b[0m ", timestamp);
    println!("{}: {}", level_colored, entry.message);

    // Print additional values if specified
    for key in additional {
        if let Some(val) = entry.fields.get(key) {
            format_additional_value(key, val);
        }
    }
}

pub fn format_with_prefix(entry: &LogEntry, config: &Config, additional: &[String], dump_all: bool, excluded: &[String]) {
    let timestamp = truncate_timestamp(&entry.timestamp);
    let level_colored = format_level_colored(&entry.level);
    let prefix_str = entry.prefix.as_deref().unwrap_or("");

    print!("\x1b[1m{:19}\x1b[0m ", timestamp);
    println!("{}: \x1b[1m\x1b[36m{}\x1b[0m {}", level_colored, prefix_str, entry.message);

    if dump_all {
        format_all_fields(entry, config, excluded);
    } else {
        for key in additional {
            if let Some(val) = entry.fields.get(key) {
                format_additional_value(key, val);
            }
        }
    }
}

pub fn format_full(entry: &LogEntry, config: &Config, _additional: &[String], excluded: &[String]) {
    let timestamp = truncate_timestamp(&entry.timestamp);
    let level_colored = format_level_colored(&entry.level);

    print!("\x1b[1m{:19}\x1b[0m ", timestamp);
    println!("{}: {}", level_colored, entry.message);

    format_all_fields(entry, config, excluded);
}

fn format_all_fields(entry: &LogEntry, config: &Config, excluded: &[String]) {
    let max_key_len = entry.fields.keys()
        .map(|k| k.len())
        .max()
        .unwrap_or(0);

    for (key, val) in &entry.fields {
        if excluded.contains(key) {
            continue;
        }

        format_field_value(key, val, max_key_len);
    }
}

fn format_field_value(key: &str, val: &JsonValue, max_len: usize) {
    match val {
        JsonValue::Array(arr) => {
            for (idx, item) in arr.iter().enumerate() {
                let key_name = if arr.len() == 1 {
                    key.to_string()
                } else {
                    format!("{}[{}]", key, idx)
                };
                print!("\x1b[1m\x1b[38;2;150;150;150m{:width$}\x1b[0m: ", key_name, width = max_len);
                match item {
                    JsonValue::String(s) => println!("\"{}\"", s),
                    _ => println!("{}", item.to_string()),
                }
            }
        }
        JsonValue::Object(_) => {
            print!("\x1b[1m\x1b[38;2;150;150;150m{:width$}\x1b[0m: ", key, width = max_len);
            println!("{}", val.to_string());
        }
        JsonValue::String(s) => {
            print!("\x1b[1m\x1b[38;2;150;150;150m{:width$}\x1b[0m: ", key, width = max_len);
            println!("{}", s);
        }
        JsonValue::Number(n) => {
            print!("\x1b[1m\x1b[38;2;150;150;150m{:width$}\x1b[0m: ", key, width = max_len);
            if n.fract() == 0.0 && n.is_finite() {
                println!("{}", *n as i64);
            } else {
                println!("{}", n);
            }
        }
        JsonValue::Bool(b) => {
            print!("\x1b[1m\x1b[38;2;150;150;150m{:width$}\x1b[0m: ", key, width = max_len);
            println!("{}", b);
        }
        JsonValue::Null => {
            print!("\x1b[1m\x1b[38;2;150;150;150m{:width$}\x1b[0m: ", key, width = max_len);
            println!("null");
        }
    }
}

fn format_additional_value(key: &str, val: &JsonValue) {
    let val_str = val.to_string();
    print!("\x1b[1m\x1b[38;2;150;150;150m{:25}\x1b[0m: ", key);
    println!("{}", val_str);
}

fn truncate_timestamp(ts: &str) -> String {
    if ts.len() >= 19 {
        ts[0..19].to_string()
    } else {
        format!("{:19}", ts)
    }
}

fn format_level_colored(level: &str) -> String {
    let level_upper = level.to_uppercase();

    let color_code = match level_upper.as_str() {
        "DEBUG" => "34",
        "INFO" => "32",
        "WARN" | "WARNING" => "33",
        "ERROR" => "31",
        _ => "35",
    };

    let fixed = if level_upper.len() > 5 {
        level_upper[0..5].to_string()
    } else {
        format!("{:>5}", level_upper)
    };

    format!("\x1b[1;{}m{}\x1b[0m", color_code, fixed)
}
