                formatter::format_full(&entry, &config, &args.additional_value, &args.excluded_value);
            } else {
                formatter::format_main(&entry, &config, &args.additional_value);
            }
        } else {
            // Non-JSON line - print as is with warning marker
            println!("[1;38;2;255;135;22m??? >[0m {}", line);
        }
    }

    Ok(())
}
